const PREGUNTAS = [
  "En el modelo de producción sin perc_ratio, ¿qué tres features concentran más de la mitad de la importancia del Random Forest y cuánto suman?",
  "¿Sobre qué conjunto se midieron la regla lineal (49.7 %) y el acuerdo final del router de confianza (74.0 %) reportados en el benchmark de DSP?",
  "En la arquitectura original del proyecto, ¿qué papel cumplía Route B (CLAP zero-shot) dentro de la clasificación combinada?",
  "¿Qué sesgo mostró CLAP zero-shot al usar prompts largos y densos en palabras clave?",
  "¿Qué balanced accuracy obtuvo el sistema de prototipos few-shot usando k=5 canciones de soporte por categoría?"
];

const corrida = $execution.id;

return PREGUNTAS.map((question) => ({ json: { question, corrida } }));

const LIMITE_LATENCIA_MS = 30000;

return $input.all().map((item, i) => {
  const enviada = $('Preguntas fijas').all()[i].json;
  const r = item.json;
  let estado = 'ok';
  let motivo = null;
  const codigo = r.statusCode ?? null;
  const latencia = r.body?.latency_ms ?? null;

  if (r.error) {
    estado = 'falla';
    motivo = `la API no responde: ${r.error.message ?? r.error}`;
  } else if (codigo !== 200) {
    estado = 'falla';
    motivo = `HTTP ${codigo}: ${r.body?.detail ?? 'sin detalle'}`;
  } else if (!r.body?.answer || !r.body.answer.trim()) {
    estado = 'falla';
    motivo = 'respuesta vacía';
  } else if (latencia > LIMITE_LATENCIA_MS) {
    estado = 'falla';
    motivo = `latencia ${Math.round(latencia)} ms supera el límite de ${LIMITE_LATENCIA_MS} ms`;
  }

  return {
    json: {
      corrida_id: String(enviada.corrida),
      pregunta: enviada.question,
      estado,
      codigo_http: codigo,
      latencia_ms: latencia,
      motivo,
    },
  };
});
